/* ---- letters: stretch each glyph's exact ink box to fill its cell (zero gaps) ---- */
var FONT = '500 100px "Manrope", sans-serif';
var OX = 90, OY = 220, CW = 360, CH = 360;

function inkViewBox(letter){
  var c = document.createElement('canvas');
  c.width = CW; c.height = CH;
  var ctx = c.getContext('2d');
  ctx.font = FONT; ctx.textAlign = 'left'; ctx.textBaseline = 'alphabetic';
  ctx.fillStyle = '#fff';
  ctx.fillText(letter, OX, OY);
  var d = ctx.getImageData(0, 0, CW, CH).data;
  var minX = CW, minY = CH, maxX = -1, maxY = -1;
  for (var y = 0; y < CH; y++){
    var row = y * CW * 4;
    for (var x = 0; x < CW; x++){
      if (d[row + x * 4 + 3] > 16){
        if (x < minX) minX = x; if (x > maxX) maxX = x;
        if (y < minY) minY = y; if (y > maxY) maxY = y;
      }
    }
  }
  if (maxX < 0) return null;
  return (minX - OX) + ' ' + (minY - OY) + ' ' + (maxX - minX + 1) + ' ' + (maxY - minY + 1);
}

function fitGlyphs(){
  document.querySelectorAll('.glyph').forEach(function(svg){
    var vb = inkViewBox(svg.querySelector('text').textContent);
    if (vb){ svg.setAttribute('viewBox', vb); svg.setAttribute('preserveAspectRatio', 'none'); }
  });
}

/* ---- junction highlights: a white square at every grid-line intersection ---- */
function placeNodes(){
  var logo = document.querySelector('.logo');
  if (!logo) return;
  logo.querySelectorAll('.node').forEach(function(n){ n.remove(); });
  var lr = logo.getBoundingClientRect();
  var seen = {};
  function addNode(px, py){
    var x = Math.round(px - lr.left - logo.clientLeft);
    var y = Math.round(py - lr.top  - logo.clientTop);
    var key = x + ',' + y;
    if (seen[key]) return;
    seen[key] = 1;
    var n = document.createElement('div');
    n.className = 'node';
    n.style.left = x + 'px';
    n.style.top  = y + 'px';
    logo.appendChild(n);
  }

  // main grid: junctions ONLY at the ends (outer top & bottom edges).
  // the inner lines that touch the letters get no junctions.
  var main = [];
  logo.querySelectorAll('.cell').forEach(function(c){ if (!c.closest('.tower')) main.push(c); });
  main.forEach(function(c, i){
    var r = c.getBoundingClientRect();
    if (i < 9){                              // top band row -> grid TOP edge
      addNode(r.left, r.top); addNode(r.right, r.top);
    } else if (i >= main.length - 9){        // bottom band row -> grid BOTTOM edge
      addNode(r.left, r.bottom); addNode(r.right, r.bottom);
    }
    // letter row -> no junctions (those lines touch the letters)
  });

  // empty box: junctions at its corners only (the ends), not internal divisions
  logo.querySelectorAll('.tower').forEach(function(t){
    var r = t.getBoundingClientRect();
    addNode(r.left, r.top);    addNode(r.right, r.top);
    addNode(r.left, r.bottom); addNode(r.right, r.bottom);
  });
}

function refresh(){ fitGlyphs(); placeNodes(); }

function run(){
  placeNodes();                 // junctions don't need the font -> place them now
  fitGlyphs();                  // first pass (may use fallback metrics)
  if (document.fonts) {
    var jobs = [];
    if (document.fonts.load)  jobs.push(document.fonts.load(FONT));
    if (document.fonts.ready) jobs.push(document.fonts.ready);
    if (jobs.length) Promise.all(jobs).then(refresh, refresh);   // re-fit with real font
  }
}

run();
window.addEventListener('load', run);
window.addEventListener('resize', function(){ placeNodes(); });

/* ---- preloader: reveal the site only after the hero image (+ fonts) load ---- */
(function(){
  var pre = document.getElementById('preloader');
  if (!pre) return;
  document.documentElement.style.overflow = 'hidden';   // lock scroll while loading
  function reveal(){
    document.documentElement.style.overflow = '';        // unlock
    pre.classList.add('hidden');
    setTimeout(function(){
      var root = document.documentElement;
      root.style.setProperty('--la', 0);            // pin hidden, then fade in
      document.body.classList.remove('loading');    // tower fades in (CSS transition)
      var t0 = null;
      function step(ts){
        if (t0 === null) t0 = ts;
        var k = Math.min((ts - t0) / 700, 1);        // 0 -> 1 over 700ms
        root.style.setProperty('--la', k);
        if (k < 1) requestAnimationFrame(step);
      }
      requestAnimationFrame(step);
    }, 750);
  }
  var jobs = [
    new Promise(function(res){
      var img = new Image();
      img.onload = img.onerror = res;
      img.src = '/home-glydi/bag.jpeg';
    }),
    new Promise(function(res){ setTimeout(res, 1100); })   /* minimum on-screen time */
  ];
  if (document.fonts && document.fonts.ready) jobs.push(document.fonts.ready);
  var safety = new Promise(function(res){ setTimeout(res, 6000); });   /* never hang */
  Promise.race([ Promise.all(jobs), safety ]).then(reveal);
})();

/* ---- pipeline: single-open accordion (opening one closes the others) ---- */
(function(){
  var items = Array.prototype.slice.call(document.querySelectorAll('.pipeline li'));
  if (!items.length) return;
  function setOpen(li, open){
    var detail = li.querySelector('.step-detail');
    var btn = li.querySelector('.step-btn');
    li.classList.toggle('is-open', open);
    if (detail) detail.classList.toggle('open', open);
    if (btn){
      btn.classList.toggle('open', open);
      btn.setAttribute('aria-expanded', open ? 'true' : 'false');
    }
  }
  items.forEach(function(li){
    var head = li.querySelector('.step-head');
    var detail = li.querySelector('.step-detail');
    if (!head || !detail) return;
    head.addEventListener('click', function(){
      var willOpen = !detail.classList.contains('open');
      items.forEach(function(other){ if (other !== li) setOpen(other, false); });   /* close the rest */
      setOpen(li, willOpen);                                                          /* toggle this one */
    });
  });
})();

/* ---- HERO MOTION ENGINE ----------------------------------------------
   One rAF loop owns .hero-bg entirely: the intro scale-down, the scroll
   parallax and the pointer drift all compose into a single transform.
   Three separate handlers would each clobber the others' transform.
   The loop only runs while the hero is on screen. Everything below the
   entrance is skipped under prefers-reduced-motion — including the word
   split, so the headline is never left in a hidden state. ------------- */
(function(){
  var hero  = document.querySelector('.hero');
  var bg    = document.querySelector('.hero-bg');
  var inner = document.querySelector('.hero-inner');
  var title = document.querySelector('.hero-title');
  if (!hero) return;
  var reduce = window.matchMedia && window.matchMedia('(prefers-reduced-motion: reduce)').matches;

  /* Headline: wrap every word so it can rise out of its own mask. Built
     here rather than in the HTML — markup that ships pre-hidden stays at
     opacity:0 forever if the script ever fails. */
  if (title && !reduce){
    var frag = document.createDocumentFragment();
    var n = 0;
    var words = function(text, accent){
      text.split(/(\s+)/).forEach(function(tok){
        if (!tok) return;
        if (/^\s+$/.test(tok)){ frag.appendChild(document.createTextNode(' ')); return; }
        var mask = document.createElement('span');
        mask.className = 'hw';
        var ink = document.createElement('i');
        ink.textContent = tok;
        if (accent) ink.className = 'accent';
        ink.style.setProperty('--d', (n * 64) + 'ms');
        n++;
        mask.appendChild(ink);
        frag.appendChild(mask);
      });
    };
    Array.prototype.forEach.call(title.childNodes, function(node){
      words(node.textContent || '', node.nodeType !== 3);
    });
    title.innerHTML = '';
    title.appendChild(frag);
  }

  /* trigger the entrance on the next frame so the transitions actually run */
  requestAnimationFrame(function(){ hero.classList.add('is-in'); });

  if (reduce) return;

  var t0 = performance.now();
  var px = 0, py = 0, tx = 0, ty = 0;   /* pointer: current vs target */
  var running = false, raf = 0;

  window.addEventListener('pointermove', function(e){
    var r = hero.getBoundingClientRect();
    if (!r.width || !r.height) return;
    tx = (e.clientX - r.width  / 2) / r.width;
    ty = (e.clientY - r.height / 2) / r.height;
  }, { passive:true });

  function frame(now){
    var intro = Math.min(1, (now - t0) / 1600);
    intro = 1 - Math.pow(1 - intro, 3);                 /* ease-out cubic */
    var p = window.scrollY / window.innerHeight;
    p = p < 0 ? 0 : (p > 1 ? 1 : p);

    px += (tx - px) * 0.055;                            /* lag the pointer */
    py += (ty - py) * 0.055;

    if (bg){
      var scale = (1.09 - 0.09 * intro) * (1 + p * 0.13);
      var x = px * -20;
      var y = py * -13 + p * 7 * window.innerHeight / 100;
      bg.style.transform = 'translate3d(' + x + 'px,' + y + 'px,0) scale(' + scale + ')';
    }
    if (inner){
      inner.style.transform = 'translateY(' + (-p * 9) + 'vh)';
      inner.style.opacity = String(1 - Math.min(1, p * 1.35));
    }
    raf = requestAnimationFrame(frame);
  }

  function begin(){ if (!running){ running = true; raf = requestAnimationFrame(frame); } }
  function halt(){ running = false; if (raf) cancelAnimationFrame(raf); }

  if ('IntersectionObserver' in window){
    new IntersectionObserver(function(entries){
      entries.forEach(function(e){ if (e.isIntersecting) { begin(); } else { halt(); } });
    }, { threshold:0 }).observe(hero);
  } else {
    begin();
  }
})();

/* ---- steps board: assemble on scroll-in.
        The .in class is added HERE, never in the markup — the board ships
        visible and only becomes animatable once this runs, so a script
        failure can never leave the four phases stuck at opacity:0. ---- */
(function(){
  var board = document.querySelector('.steps-board');
  if (!board) return;
  var reduce = window.matchMedia && window.matchMedia('(prefers-reduced-motion: reduce)').matches;
  if (reduce || !('IntersectionObserver' in window)){ board.classList.add('in'); return; }
  var io = new IntersectionObserver(function(entries){
    entries.forEach(function(e){
      if (!e.isIntersecting) return;
      e.target.classList.add('in');
      io.unobserve(e.target);
    });
  }, { threshold:0.18 });
  io.observe(board);
})();

/* ---- mobile menu toggle ---- */
(function(){
  var nav = document.querySelector('.nav');
  var toggle = document.getElementById('navToggle');
  if (!nav || !toggle) return;
  toggle.addEventListener('click', function(){
    var open = nav.classList.toggle('open');
    toggle.setAttribute('aria-expanded', open ? 'true' : 'false');
  });
  nav.querySelectorAll('.nav-links a').forEach(function(a){
    a.addEventListener('click', function(){
      nav.classList.remove('open');
      toggle.setAttribute('aria-expanded', 'false');
    });
  });
})();

